package de.ostms.lc.document.service;

import de.ostms.lc.document.domain.LcDocument;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;

/** Typical wording of clean documents (invoice, bill of lading, packing list, credit references); ambiguous 05/12/2026 and rare labels are left out on purpose. */
class CleanDocumentRecognitionTest {
 static LcDocument run(String text){var d=new LcDocument();d.setOriginalFilename("x.txt");d.setContentType("text/plain");d.setContent(text.getBytes(StandardCharsets.UTF_8));new DocumentExtractionService().extract(d);return d;}
 @Test void usualLabelsOfCleanDocumentsAreRecognised(){
  var out=new StringBuilder("\n");
  String[][] dates={{"Date: 05.12.2026","2026-12-05"},{"Date of issue: 5 December 2026","2026-12-05"},{"Dated: 05-Dec-2026","2026-12-05"},{"Place and date of issue: Hamburg, 05.12.2026","2026-12-05"},{"Hamburg, den 05.12.2026","2026-12-05"},{"Datum: 05.12.2026","2026-12-05"},{"Rechnungsdatum: 05.12.2026","2026-12-05"},{"Ausstellungsdatum: 05.12.2026","2026-12-05"},{"Date of invoice: 2026-12-05","2026-12-05"},{"Issued on 05.12.2026","2026-12-05"},{"Invoice date\n05.12.2026","2026-12-05"},{"Date of issue\n05 DEC 2026","2026-12-05"},{"Ausgestellt am 05.12.2026","2026-12-05"},{"Lieferdatum: 05.12.2026\nRechnungsdatum: 06.12.2026","2026-12-06"},{"Date issued: 12/05/2026 (MM/DD)","?"},{"Packing list date: 05.12.2026","2026-12-05"},{"Bill of lading date: 05.12.2026","2026-12-05"},{"Date of shipment: 05.12.2026","-"}};
  for(var p:dates){var r=DocumentDateDetector.detect("DOCUMENT\n"+p[0]+"\nMore text");String got=r.date()==null?"-":r.date().toString();out.append(got.equals(p[1])||p[1].equals("?")?"ok   ":"FAIL ").append("DATE   ").append(p[0].replace("\n"," | ")).append(" -> ").append(got).append('\n');}
  String[][] amounts={{"Total amount: EUR 125,000.00","125000.00"},{"Total: EUR 125.000,00","125000.00"},{"Gesamtbetrag: 125.000,00 EUR","125000.00"},{"Invoice total EUR 1,250.00","1250.00"},{"Amount: USD 1,000.00","1000.00"},{"Rechnungsbetrag EUR 1.000,00","1000.00"},{"TOTAL USD 12,345.67","12345.67"},{"Total (CIF) EUR 1,000.00","1000.00"},{"Grand total: € 1.000,00","1000.00"},{"Total invoice amount: CHF 2'500.00","2500.00"},{"Amount due: GBP 99.50","99.50"},{"Summe: 1.000,00 EUR","1000.00"},{"Endbetrag EUR 1.000,00","1000.00"},{"Total amount payable EUR 4,000.00","4000.00"},{"Total value: JPY 1,000,000","1000000"},{"Invoice value EUR 7,500.00","7500.00"},{"TOTAL CIF SHANGHAI: EUR 360.000,00","360000.00"},{"Total EUR 360.000,00","360000.00"}};
  for(var p:amounts){var d=run("COMMERCIAL INVOICE\nInvoice No.: INV-1\n"+p[0]+"\n");String got=d.getExtractedAmount()==null?"-":d.getExtractedAmount().toPlainString();out.append(new java.math.BigDecimal(p[1]).compareTo(d.getExtractedAmount()==null?java.math.BigDecimal.valueOf(-1):d.getExtractedAmount())==0?"ok   ":"FAIL ").append("AMOUNT ").append(p[0]).append(" -> ").append(got).append(' ').append(d.getExtractedCurrency()).append('\n');}
  String[][] numbers={{"Invoice No.: INV-2026-0815","INV-2026-0815"},{"Invoice Number 2026-0815","2026-0815"},{"Rechnungsnummer: RE-2026-1","RE-2026-1"},{"Rechnung Nr. 4711","4711"},{"Invoice No. 12345 Date: 05.12.2026","12345"},{"Invoice no: A/123/26","A/123/26"},{"COMMERCIAL INVOICE ORIGINAL","-"},{"Tax Invoice No: T-99","T-99"},{"Invoice #5567","5567"},{"Invoice No.\nINV-77","INV-77"},{"Rechn.-Nr.: 8812","8812"},{"Belegnummer: B-1","B-1"}};
  for(var p:numbers){var d=run(p[0]+"\nLC Reference: LCB123456\n");String got=d.getExtractedDocumentNumber()==null?"-":d.getExtractedDocumentNumber();out.append(got.equals(p[1])?"ok   ":"FAIL ").append("INVNO  ").append(p[0].replace("\n"," | ")).append(" -> ").append(got).append('\n');}
  String[][] refs={{"Documentary Credit Number: 111LC100020067","111LC100020067"},{"L/C No. 123456789","123456789"},{"Akkreditiv-Nr.: 4711-26","4711-26"},{"Credit Number: DC2026001","DC2026001"},{"DC No.: ABC12345","ABC12345"},{"LC-Nr.: LCB0001234","LCB0001234"},{"L/C Number: 5090181501","5090181501"},{"Letter of Credit No.: ILC20260123","ILC20260123"},{"Credit No.\nLCB0310202600653","LCB0310202600653"},{"Documentary credit no. 111 LC 100020067","?"},{"under L/C No. 5090181501 dated 12.07.2026","5090181501"},{"Reference to documentary credit: LCB0310202600653","LCB0310202600653"},{"Our reference: LCB1234567","-"},{"Akkreditiv Nr. 112233","112233"},{"Kreditbrief Nr. 998877","-"}};
  for(var p:refs){var d=run("DOCUMENT\n"+p[0]+"\n");String got=d.getExtractedReference()==null?"-":d.getExtractedReference();out.append(got.equals(p[1])||p[1].equals("?")?"ok   ":"FAIL ").append("LCREF  ").append(p[0].replace("\n"," | ")).append(" -> ").append(got).append('\n');}
  String[][] other={{"B/L No.: HLXU-2026-4711","BL"},{"Bill of Lading No. MAEU123456789","BL"},{"Packing List No.: PL-2026-0815","PL"},{"Air Waybill No.: 057-12345675","AWB"},{"AWB No. 176-12345678","AWB"},{"Certificate No.: CO-2026-3377","CERT"},{"Policy No.: POL-123456","POL"},{"Delivery note no.: LS-4711","DN"}};
  for(var p:other){var d=run("DOC\n"+p[0]+"\n");out.append(d.getExtractedDocumentNumber()==null?"FAIL ":"ok   ").append("OTHERNO ").append(p[0]).append(" -> ").append(d.getExtractedDocumentNumber()).append('\n');}
  var failures=out.toString().lines().filter(l->l.startsWith("FAIL")).toList();
  org.assertj.core.api.Assertions.assertThat(failures).as(out.toString()).isEmpty();
 }
}
